using System;using System.Linq;using System.Collections.Generic;
namespace LoopPedal {
static class CaptureChecks {
 static void Check(bool b,string message){if(!b)throw new Exception(message);}
 public static void Run(List<string> log){
 using(var buffer=new RecordedAudio(CaptureBlocks.Samples*3+102)){long misses=CaptureBlocks.EmergencyAllocations;int n=CaptureBlocks.Samples*3+102;for(int i=0;i<n;i++)buffer.Add((i%103-51)*.025f);var copy=buffer.ToArray();for(int i=0;i<n;i++)Check(copy[i]==(i%103-51)*.025f,"Blocked capture changed sample "+i);var slice=new float[100];buffer.CopyTo(CaptureBlocks.Samples-49,slice,0,100);for(int i=0;i<100;i++)Check(slice[i]==copy[CaptureBlocks.Samples-49+i],"Cross-block capture copy");Check(CaptureBlocks.EmergencyAllocations==misses,"Warm capture allocated audio blocks on callback");log.Add("PASS fixed recording blocks: bit-exact over boundaries, HDR floats retained, cross-block copy; no callback block allocations");}
 foreach(int at in new[]{0,1,17000,47999})using(var e=new Engine()){e.Destructive=true;e.LoopFrames=48000;var old=Enumerable.Repeat(.05f,96000).ToArray();e.Layers.Add(new Layer{Original=old,Audio=old,SmoothL=1,SmoothR=1});var take=new float[96000];for(int i=0;i<48000;i++)take[2*i]=take[2*i+1]=(float)(-.7+1.4*i/47999);e.CommitLayer(new Layer{Original=take,Audio=take,Offset=at});var pcm=new float[96000];e.Mix(pcm,48000);e.Frame=at+48000-500;e.Mix(pcm,48000);double jump=0;for(int i=1;i<48000;i++)jump=Math.Max(jump,Math.Abs(pcm[2*i]-pcm[2*(i-1)]));Check(jump<.015,"Destructive splice clicks at offset "+at+": "+jump);Check(e.Layers.Count==1,"Destructive layer count");log.Add("PASS destructive splice offset="+at+" maximum adjacent-sample jump="+jump);}
 using(var e=new Engine()){e.Destructive=true;e.LoopFrames=48000;var original=Enumerable.Repeat(.1f,96000).ToArray();e.Layers.Add(new Layer{Original=original,Audio=original});var input=new Input(new SourceChoice{Name="In 2",Left=1,Right=1});e.Inputs.Add(input);e.Frame=17000;e.Begin(true);var data=Enumerable.Repeat(.2f,96000).ToArray();input.Feed(data,data.Length,2,e.AudioFrame);e.Finish(false);Check(e.Layers.Single().Original.All(v=>Math.Abs(v-.3f)<.000001),"Destructive overdub changed gain beyond old + new");var pcm=new float[96000];e.Mix(pcm,48000);Check(pcm.Skip(8192).All(v=>Math.Abs(v-.3f)<.000001),"Destructive playback level differs from old + new");log.Add("PASS mono In 2 destructive overdub: .1 existing + .2 input = .3 stored and played; no normalization or level boost");}
 }
}
}
